WITH filtered_departments AS (SELECT * FROM departments WHERE dept_name IN ('HR', 'Sales', 'Engineering') AND budget <= 2827000 AND budget < 1733000), agg AS (SELECT CASE WHEN budget >= 3697000 THEN 'high' WHEN budget >= 1634000 THEN 'mid' ELSE 'low' END budget_bucket, location, SUM(budget) total_budget, SORT_ARRAY(COLLECT_SET(dept_name)) dept_name_list FROM filtered_departments GROUP BY CASE WHEN budget >= 3697000 THEN 'high' WHEN budget >= 1634000 THEN 'mid' ELSE 'low' END, location) SELECT budget_bucket, location, total_budget FROM agg ORDER BY budget_bucket, location LIMIT 10;
